fun look_up_code_owner(self: &Referral, referral_code: String): address {
    *self.code_owner.borrow(referral_code)
}

fun update_user_rebate<CoinType>(self: &mut Referral, who: address, rebates: Balance<CoinType>) {
    if (rebates.value() == 0) {
        rebates.destroy_zero();
        return
    };

    self.record_user_rebates<CoinType>(who, rebates.value());
    self.join_rebate_balance<CoinType>(rebates);
}

fun record_user_rebates<CoinType>(self: &mut Referral, who: address, amount: u64) {
    let coin_type = type_name::with_defining_ids<CoinType>();

    if (!self.user_rebates_records.contains(who)) {
        let mut user_rebates = vec_map::empty<TypeName, u64>();
        user_rebates.insert(coin_type, amount);
        self.user_rebates_records.add( who, user_rebates);
        return
    };

    let user_rebates = self.user_rebates_records.borrow_mut( who);
    if (!user_rebates.contains( &coin_type)) {
        user_rebates.insert( coin_type, amount);
        return
    };

    let current = user_rebates.get_mut(&coin_type);
    *current = *current + amount;
}

fun join_rebate_balance<CoinType>(self: &mut Referral, rebates: Balance<CoinType>) {
    let coin_type = type_name::with_defining_ids<CoinType>();
    if (self.rebates.contains(coin_type)) {
        let balance = self.rebates.borrow_mut<TypeName, Balance<CoinType>>(coin_type);
       balance.join(rebates);
    } else {
        self.rebates.add(coin_type, rebates);
    }
}

/// generate a random string of specified length using characters a-z and 0-9
fun generate_random_string(
    random: &Random,
    length: u64,
    ctx: &mut TxContext
): String {
    let mut generator = random::new_generator(random, ctx);
    let mut chars   = vector::empty<u8>();

    length.do!(|_| {
        // generate random index 0-35 (36 characters: 0-9 + a-z)
        let rand = generator.generate_u8();
        let idx = rand % 36;

        let char_byte = if (idx < 10) {
            // 0-9: ASCII 48-57
            48 + idx
        } else {
            // a-z: ASCII 97-122 (idx 10-35 maps to 'a'-'z')
            87 + idx  // 97 - 10 = 87
        };
        chars.push_back(char_byte);
    });

    string::utf8(chars)
}

